import { execFileSync } from 'node:child_process';

const EXE = '/workspace/dataset/test4_executable';

const probes = [
  ['b1_basic', 'select 1'],
  ['b2_leading_ws', '  select 1'],
  ['b3_trailing_ws', 'select 1  '],
  ['b4_internal_ws', 'select  1   from t'],
  ['b5_two_stmts', 'select 1; select 2'],
  ['b6_space_before_semi', 'select 1 ; select 2'],
  ['b7_newlines_between', 'select 1;\n\n select 2'],
  ['b8_single_comment_between', 'select 1; -- comment\n select 2'],
  ['b9_multi_comment_between', 'select 1; /* comment */ select 2'],
  ['b10_leading_single_comment', '-- lead\nselect 1'],
  ['b11_leading_multi_comment', '/* lead */ select 1'],
  ['b12_special_words', 'select a.month, month.a, f(a), in(1), values(1), case when 1 then 2 end from t'],
  ['b13_quoted', "select `month`, \"month\", 'month' from t"],
  ['b14_dollar', 'select $$month$$, $tag$x$tag$ from t'],
  ['b15_empty', ''],
  ['b16_only_semi', ';'],
  ['b17_double_semi', 'select 1;;select 2'],
  ['b18_mixed_case', 'SeLeCt MoNtH FrOm t'],
  ['b19_placeholders', 'select 1 from t where a=? and b=:x and c=$1 and d=%s'],
  ['b20_cast_ops', "select 1::int, 'a' || 'b', x := 5"],
  ['b21_numbers', 'select e1, 1abc, 0x1F, 1.5e-3, .5, -5 from t'],
  ['b23_newline_inside', 'select 1\nfrom t'],
  ['b24_semi_in_parens', 'select (1;2)'],
  ['b25_begin_end', 'begin select 1; end'],
  ['b26_case_then_semi', 'select case when a then 1 end; select 2'],
  ['b27_tabs', 'select\t1\tfrom\tt'],
  ['b28_unicode', 'select café, año from t'],
  ['b29_comment_trailing', 'select 1 -- trail'],
  ['b30_comment_inline', 'select /* x */ 1 from t'],
  ['b31_ws_only', '   '],
  ['b32_hash_comment', 'select 1 # hash\nfrom t'],
  ['b33_semi_only_then_ws', 'select 1;   '],
  ['b34_nested_parens', 'select ((select 1)); select 2'],
  ['b35_string_with_semi', "select 'a;b'; select 2"],
  ['b36_end_without_begin', 'select end'],
];

for (const [name, input] of probes) {
  let out, code = 0;
  try {
    out = execFileSync(EXE, ['--a', input], { encoding: 'utf8' });
  } catch (e) {
    code = e.status;
    out = (e.stdout || '') + '|STDERR:' + (e.stderr || '');
  }
  console.log(`${name}: in=${JSON.stringify(input)} rc=${code} out=${JSON.stringify(out)}`);
}

