import { execFileSync, spawnSync } from 'node:child_process';
const EXE = '/workspace/dataset/test4_executable';
const cases = [
  ['no_args', []],
  ['help', ['--help']],
  ['h', ['-h']],
  ['unknown', ['--b', 'x']],
  ['a_equals', ['--a=select 1']],
  ['a_missing_value', ['--a']],
  ['extra_positional', ['--a', 'select 1', 'extra']],
  ['a_twice', ['--a', 'select 1', '--a', 'select 2']],
  ['a_dash_value', ['--a', '-5']],
  ['a_dashdash', ['--a', '--select']],
  ['abbrev', ['--', '--a', 'select 1']],
];
for (const [name, args] of cases) {
  const r = spawnSync(EXE, args, { encoding: 'utf8' });
  console.log(`${name}: args=${JSON.stringify(args)} rc=${r.status}`);
  if (r.stdout) console.log(`  stdout=${JSON.stringify(r.stdout)}`);
  if (r.stderr) console.log(`  stderr=${JSON.stringify(r.stderr)}`);
}

import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
const EXE = '/workspace/dataset/test4_executable';

const words = readFileSync('/workspace/scratch/candidates.txt', 'utf8')
  .split(/\s+/).filter(Boolean);
const uniq = [...new Set(words)];
console.log('candidates:', uniq.length);

const keywords = [];
const CHUNK = 80;
for (let i = 0; i < uniq.length; i += CHUNK) {
  const chunk = uniq.slice(i, i + CHUNK);
  const sql = 'select ' + chunk.join(',') + ' from t';
  const out = execFileSync(EXE, ['--a', sql], { encoding: 'utf8' });
  let body = out.trimEnd();
  if (!body.startsWith('SELECT ') || !body.endsWith(' FROM t')) {
    console.log('BAD OUTPUT for chunk starting', chunk[0], JSON.stringify(out));
    continue;
  }
  body = body.slice('SELECT '.length, body.length - ' FROM t'.length);
  const toks = body.split(',');
  if (toks.length !== chunk.length) {
    console.log('TOKEN COUNT MISMATCH', chunk[0], toks.length, chunk.length);
    continue;
  }
  for (let j = 0; j < chunk.length; j++) {
    if (toks[j] === chunk[j].toUpperCase() && toks[j] !== chunk[j]) {
      keywords.push(chunk[j]);
    } else if (toks[j] !== chunk[j]) {
      console.log('TRANSFORMED:', chunk[j], '->', toks[j]);
    }
  }
}
console.log('KEYWORD_COUNT:', keywords.length);
console.log(keywords.join(' '));

