cd /workspace/scratch && node -e "
import('node:child_process').then(async ({execFileSync}) => {
  const {readFileSync, writeFileSync} = await import('node:fs');
  const EXE='/workspace/dataset/test4_executable';
  const words=[...new Set(readFileSync('candidates.txt','utf8').split(/\s+/).filter(Boolean))];
  const keywords=[]; const mism=[];
  for (let i=0;i<words.length;i+=80){
    const chunk=words.slice(i,i+80);
    const out=execFileSync(EXE,['--a','select '+chunk.join(',')+' from t'],{encoding:'utf8'}).trimEnd();
    const body=out.slice(7,out.length-7);
    const toks=body.split(',');
    if(toks.length!==chunk.length){mism.push(chunk[0]);continue;}
    for(let j=0;j<chunk.length;j++){
      if(toks[j]===chunk[j].toUpperCase()&&toks[j]!==chunk[j]) keywords.push(chunk[j]);
      else if(toks[j]!==chunk[j]) console.log('TRANSFORMED:',chunk[j],'->',toks[j]);
    }
  }
  writeFileSync('keywords_found.txt', keywords.join(' ')+'\n');
  console.log('saved', keywords.length, 'mismatch chunks:', mism.length);
});
"

