import { execFileSync } from 'node:child_process';
const EXE = '/workspace/dataset/test4_executable';

// Wave 2: extra keyword candidates (not tested in wave 1)
const extra = `upsert directory bfile buckets avro sequencefile textfile rcfile
uniontype mediumint mediumtext longtext longblob mediumblob tinyblob tinytext
auto_increment autoincrement zerofill unsigned signed engine charset databases
processlist grants settings wal plpgsql signal resignal arrays maps structs
int integer smallint varchar char text date timestamp boolean real numeric
decimal number float interval bigint tinyint blob xml json jsonb uuid bytea
regclass oid xid serial bigserial smallserial money double character time
varying precision zone at local session transaction work read write only
deferrable initially check unique primary foreign references constraint
exclusion collate cascaded restrict cascade action no inherit oids without
with recursive materialized temp temporary unlogged global logged table if
exclude ties others groups nulls lead lag rank dense_rank row_number ntile
first_value last_value nth_value cume_dist percent_rank sysdate rowid rownum
level connect_by isodow epoch dow doy century millennium microseconds
milliseconds key keys column columns schema tables database databases index
view sequence trigger function procedure aggregate operator type domain
extension policy rule publication subscription statistics server wrapper
event listen notify unlisten lock share mode nowait skip locked returning
overriding system user session_user current_user current_role current_catalog
current_schema current_path localtime localtimestamp array row asymmetric
symmetric placing variadic window partition over range rows unbounded
preceding following current filter within collation characteristics
`.split(/\s+/).filter(Boolean);

const uniq = [...new Set(extra)];
const keywords = [];
for (let i = 0; i < uniq.length; i += 80) {
  const chunk = uniq.slice(i, i + 80);
  const out = execFileSync(EXE, ['--a', 'select ' + chunk.join(',') + ' from t'], { encoding: 'utf8' }).trimEnd();
  const toks = out.slice(7, out.length - 7).split(',');
  if (toks.length !== chunk.length) { console.log('MISMATCH', chunk[0]); continue; }
  for (let j = 0; j < chunk.length; j++) {
    if (toks[j] === chunk[j].toUpperCase() && toks[j] !== chunk[j]) keywords.push(chunk[j]);
    else if (toks[j] !== chunk[j]) console.log('TRANSFORMED:', chunk[j], '->', toks[j]);
  }
}
console.log('WAVE2_NEW_KEYWORDS:', keywords.join(' ') || '(none)');

// Serializer quote-tracking edge cases
const ser = [
  ['r1_dq_in_str', "select 'a''  \n b'"],
  ['r2_crlf_in_str', "select 'a\r\nb'"],
  ['r3_dq_trail', 'select "a  \n b"'],
  ['r4_bt_trail', 'select `a  \n b`'],
  ['r7_unterm_str_nl', "select 'unterm \n x"],
  ['r8_nl_in_str_mid', "select 'p\nq', 'r  \n s'"],
  ['r9_str_after_nl', "select 'a'\n, 'b'"],
];
for (const [name, input] of ser) {
  const out = execFileSync(EXE, ['--a', input], { encoding: 'utf8' });
  console.log(`${name}: in=${JSON.stringify(input)} out=${JSON.stringify(out)}`);
}
